mapper.select:
select id, event_id as eventId, trace_id as traceId, request_id as requestId, user_id as userId, username,
       auth_event_type as authEventType, auth_channel as authChannel, request_uri as requestUri,
       request_method as requestMethod, client_ip as clientIp, client_location as clientLocation,
       user_agent as userAgent, device_type as deviceType, http_status as httpStatus,
       result_status as resultStatus, failure_code as failureCode, failure_message as failureMessage,
       token_id as tokenId, occurred_at as occurredAt
from log_auth_record


        and username like concat('%', #{username}, '%')


        and auth_event_type = #{authEventType}


        and result_status = #{resultStatus}


        and occurred_at >= #{startTime}


        and occurred_at <= #{endTime}


order by occurred_at desc
